parameters.jsCode:
const items = ($json || []).filter(p => {
  const t = (p.name || '') + ' ' + (p.short_description || '') + ' ' + (p.description || '');
  // Skip monitor sizes (those genuinely use inches in AR e-commerce too)
  if (/monitor|display|screen|tv|شاشة/i.test(p.name)) return false;
  return /\b\d+(\.\d+)?\s*(ft|feet|foot|in|inch|inches|lb|lbs|pound|pounds|oz|ounce|ounces|gal|gallon|gallons|mi|mile|miles)\b/i.test(t);
});
return items.map(p => ({ json: p }));

parameters.jsonBody:
={
  "model": "qwen2.5:7b",
  "prompt": "Convert imperial units to metric in this Arabic/English text. Rules: convert ft, inch, lb, oz, gal, miles to m, cm, kg, g, L, km. Round to 1 decimal. Output JSON only: { \"name\": <converted name>, \"description\": <converted description> }. Keep brand names, model numbers, and monitor screen sizes (e.g. 27\") unchanged.\n\nName: " + $json.name + "\nDescription: " + ($json.short_description || $json.description || '').slice(0, 1500),
  "stream": false,
  "format": "json",
  "options": { "temperature": 0.05, "num_predict": 600 }
}

parameters.jsCode:
let parsed; try { parsed = JSON.parse($json.response); } catch(e) { throw new Error('Bad JSON from LLM: ' + $json.response.slice(0,120)); }
if (!parsed.name && !parsed.description) throw new Error('Empty result');
return { json: { ...$('Filter true imperial').item.json, converted: parsed } };
